def EquivalentNorms {B : Type*} (n m : B → ℝ) : Prop :=
  ∃ c : ℝ, 0 < c ∧ ∃ C : ℝ, 0 < C ∧
    ∀ x, c * n x ≤ m x ∧ m x ≤ C * n x

